-- Lebensmittel-Katalog in nut_foods (eine einzige Tabelle für alles)
--
-- Vorher: Die 317 Ampel-Lebensmittel standen fest im App-Code (foods.js),
-- nut_foods enthielt nur eigene/überschriebene Einträge.
-- Nachher: nut_foods enthält zusätzlich den globalen Katalog
--   owner_id IS NULL  -> Katalogzeile (für alle angemeldeten Nutzer lesbar,
--                        schreiben nur per Migration/Service-Role)
--   seed_id           -> stabile Zahlen-Id der Katalogzeile (1..317 wie bisher,
--                        neue ab 318). Rezepte zeigen per foodId darauf, und
--                        override_of verweist darauf.
--   owner_id gesetzt  -> eigenes Lebensmittel oder persönliche Überschreibung
--                        eines Katalogeintrags (override_of = seed_id)
--
-- Ausführen:
--   docker exec -i supabase-db psql -U postgres -d postgres -v ON_ERROR_STOP=1 \
--     < supabase/nutrition_catalog_migration.sql
-- Läuft in einer Transaktion und ist wiederholbar (ON CONFLICT DO NOTHING).
--
-- Bereinigt gegenüber foods.js:
--   * glutenfrei/laktosefrei werden aus den Allergenen abgeleitet (vorher
--     invertiert/unvollständig), Allergen 'Gluten (Bier)' -> 'Gluten'
--   * Tag 'Omega-3' -> 'Omega-3 reich' (so heißt er in der Filterleiste)
--   * 5 Duplikate entfernt (Ids 101, 147, 189, 193, 219); Zutaten in nut_recipes werden auf
--     die behaltene Id umgehängt

begin;

alter table public.nut_foods alter column owner_id drop not null;
alter table public.nut_foods add column if not exists seed_id integer;

create unique index if not exists nut_foods_catalog_seed_uidx
  on public.nut_foods (seed_id) where owner_id is null;

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'nut_foods_catalog_seed_check') then
    alter table public.nut_foods
      add constraint nut_foods_catalog_seed_check check (owner_id is not null or seed_id is not null);
  end if;
end $$;

drop policy if exists "katalog lesbar" on public.nut_foods;
create policy "katalog lesbar" on public.nut_foods
  for select to authenticated
  using (owner_id is null);

insert into public.nut_foods
  (seed_id, name, food_group, category, unit, kcal, protein, carbs, sugar, fat, satfat, fiber, salt,
   vitamins, minerals, micros_other, allergens, glutenfrei, laktosefrei, tags, diet)
