-- Rezepte: Zutaten der entfernten Duplikate auf die behaltene Id umhängen
update public.nut_recipes r
set ingredients = (
  select jsonb_agg(
    case when jsonb_typeof(i->'foodId') = 'number' and (i->>'foodId')::int in (101, 147, 189, 193, 219)
      then jsonb_set(i, '{foodId}', to_jsonb(case (i->>'foodId')::int when 101 then 237 when 147 then 155 when 189 then 53 when 193 then 59 when 219 then 109 end))
      else i end
    order by ord)
  from jsonb_array_elements(r.ingredients) with ordinality as t(i, ord))
where exists (
  select 1 from jsonb_array_elements(r.ingredients) i
  where jsonb_typeof(i->'foodId') = 'number' and (i->>'foodId')::int in (101, 147, 189, 193, 219));

-- Kontrolle: Erwartet 312 Katalogzeilen
select count(*) as katalog_zeilen from public.nut_foods where owner_id is null;

commit;
